contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 spend, uint256 over) public {
        require(over > 0);
        uint256 supply0 = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(c.balanceOf(address(this)) == supply0);
        c.transfer(address(0xdead), spend); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 recvBefore = c.balanceOf(address(0xdead)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(balBefore < over);
        bool reverted;
        c.transfer(address(0xbeef), over); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.balanceOf(address(this)) == balBefore && c.balanceOf(address(0xbeef)) == 0 && c.balanceOf(address(0xdead)) == recvBefore && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
