pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 spend, uint256 over) internal {
        vm.assume(over > 0);
        uint256 supply0;
        try c.totalSupply() returns (uint256 __r) { supply0 = __r; } catch { return; }
        vm.assume(c.balanceOf(address(this)) == supply0);
        try c.transfer(address(0xdead), spend) {} catch { return; }
        uint256 balBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 recvBefore;
        try c.balanceOf(address(0xdead)) returns (uint256 __r) { recvBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        vm.assume(balBefore < over);
        bool reverted;
        try c.transfer(address(0xbeef), over) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.balanceOf(address(this)) == balBefore && c.balanceOf(address(0xbeef)) == 0 && c.balanceOf(address(0xdead)) == recvBefore && c.totalSupply() == supplyBefore);
    }

    function testFuzz_run(uint256 spend, uint256 over) public {
        _run(spend, over);
    }

    receive() external payable {}
}
